//! Non-stratified dielectrics: explicit dielectric boxes and conformal rules
//! (design M2c §3.1, §6).
//!
//! A box overrides the stratified stack inside it. A conformal rule grows the
//! conductor boxes it selects laterally by `side` and upwards by `top`, and
//! the grown region minus those boxes is a shell of permittivity `eps_r`
//! (generated by the solver from the current geometry, design M2c §6.2).

use faradice_core::BoxId;
use faradice_geom::{Aabb, Geometry};

/// An axis-aligned box of dielectric that overrides the stack.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct DielectricBox {
    /// The box (µm).
    pub region: Aabb,
    /// Relative permittivity.
    pub eps_r: f64,
}

/// Conformal shells around a set of conductor boxes (one layer).
#[derive(Debug, Clone, PartialEq)]
pub struct ConformalRule {
    /// Name of the layer the rule was written for (reports only).
    pub layer: String,
    /// The conductor boxes that get a shell.
    pub boxes: Vec<BoxId>,
    /// Lateral thickness (µm, ≥ 0).
    pub side: f64,
    /// Thickness above the conductor tops (µm, ≥ 0).
    pub top: f64,
    /// Relative permittivity of the shell.
    pub eps_r: f64,
}

/// Dielectric boxes and conformal rules, on top of the stratified stack.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct DielectricRegions {
    /// Explicit boxes; they must not overlap each other, and they win over shells.
    pub boxes: Vec<DielectricBox>,
    /// Conformal rules; a later rule wins over an earlier one where shells overlap.
    pub conformal: Vec<ConformalRule>,
}

impl DielectricRegions {
    /// `true` if there is nothing to add to the stack (no boxes, and no rule
    /// that selects a conductor box).
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.boxes.is_empty() && self.conformal.iter().all(|r| r.boxes.is_empty())
    }

    /// Smallest box containing every explicit box and every grown conductor
    /// box of the rules (a superset of the material), if there is any.
    #[must_use]
    pub fn extent(&self, geom: &Geometry) -> Option<Aabb> {
        let grown = self.conformal.iter().flat_map(|r| {
            r.boxes.iter().map(move |&b| {
                let c = geom.boxes()[b.index()];
                let (lo, hi) = (c.min(), c.max());
                Aabb::new(
                    [lo[0] - r.side, lo[1] - r.side, lo[2]],
                    [hi[0] + r.side, hi[1] + r.side, hi[2] + r.top],
                )
                .unwrap_or(c)
            })
        });
        self.boxes
            .iter()
            .map(|b| b.region)
            .chain(grown)
            .reduce(|a, b| a.union(&b))
    }

    /// Validates the regions against the conductor geometry.
    ///
    /// # Errors
    ///
    /// A message describing the first violation: a permittivity that is not
    /// finite and ≥ 1, a negative or non-finite thickness, a rule with zero
    /// side and top, an unknown or repeated box id, or two overlapping
    /// explicit boxes (touching is allowed).
    pub fn validate(&self, geom: &Geometry) -> Result<(), String> {
        let ok_eps = |e: f64| e.is_finite() && e >= 1.0;
        for (i, b) in self.boxes.iter().enumerate() {
            if !ok_eps(b.eps_r) {
                return Err(format!("dielectric box {i}: eps_r must be finite and >= 1"));
            }
        }
        if let Some((i, j)) = first_overlap(&self.boxes) {
            return Err(format!("dielectric boxes {i} and {j} overlap"));
        }
        let n = geom.boxes().len();
        for r in &self.conformal {
            let name = &r.layer;
            if !ok_eps(r.eps_r) {
                return Err(format!(
                    "conformal rule `{name}`: eps_r must be finite and >= 1"
                ));
            }
            let ok_t = |t: f64| t.is_finite() && t >= 0.0;
            if !(ok_t(r.side) && ok_t(r.top)) {
                return Err(format!(
                    "conformal rule `{name}`: side and top must be finite and >= 0"
                ));
            }
            if r.side == 0.0 && r.top == 0.0 {
                return Err(format!(
                    "conformal rule `{name}`: side and top must not both be 0"
                ));
            }
            let mut seen = vec![false; n];
            for b in &r.boxes {
                let Some(s) = seen.get_mut(b.index()) else {
                    return Err(format!("conformal rule `{name}`: unknown {b}"));
                };
                if std::mem::replace(s, true) {
                    return Err(format!("conformal rule `{name}`: {b} is listed twice"));
                }
            }
        }
        Ok(())
    }
}

/// First pair of explicit boxes whose interiors overlap (a sweep over x).
fn first_overlap(boxes: &[DielectricBox]) -> Option<(usize, usize)> {
    let mut order: Vec<usize> = (0..boxes.len()).collect();
    order.sort_by(|&a, &b| {
        boxes[a].region.min()[0]
            .total_cmp(&boxes[b].region.min()[0])
            .then(a.cmp(&b))
    });
    let mut active: Vec<usize> = Vec::new();
    let mut found: Option<(usize, usize)> = None;
    for &i in &order {
        let bi = &boxes[i].region;
        active.retain(|&j| boxes[j].region.max()[0] > bi.min()[0]);
        for &j in &active {
            let bj = &boxes[j].region;
            let overlap = (0..3).all(|a| bi.min()[a] < bj.max()[a] && bj.min()[a] < bi.max()[a]);
            if overlap {
                let pair = (i.min(j), i.max(j));
                if found.is_none_or(|f| pair < f) {
                    found = Some(pair);
                }
            }
        }
        active.push(i);
    }
    found
}

#[cfg(test)]
mod tests {
    use super::*;
    use faradice_geom::GeometryBuilder;

    fn geom() -> Geometry {
        let mut g = GeometryBuilder::new();
        let a = g.net("a").unwrap();
        g.add_box(a, Aabb::from_array([0.0, 0.0, 0.0, 1.0, 1.0, 1.0]).unwrap())
            .unwrap();
        g.build().unwrap()
    }

    fn dbox(c: [f64; 6], eps_r: f64) -> DielectricBox {
        DielectricBox {
            region: Aabb::from_array(c).unwrap(),
            eps_r,
        }
    }

    fn rule(boxes: Vec<BoxId>, side: f64, top: f64) -> ConformalRule {
        ConformalRule {
            layer: "met1".into(),
            boxes,
            side,
            top,
            eps_r: 3.5,
        }
    }

    #[test]
    fn empty_and_valid() {
        let g = geom();
        let mut r = DielectricRegions::default();
        assert!(r.is_empty());
        r.conformal.push(rule(Vec::new(), 0.03, 0.0));
        assert!(r.is_empty(), "a rule without boxes adds nothing");
        r.conformal[0].boxes.push(BoxId::new(0));
        assert!(!r.is_empty());
        r.boxes.push(dbox([2.0, 0.0, 0.0, 3.0, 1.0, 1.0], 7.0));
        r.boxes.push(dbox([3.0, 0.0, 0.0, 4.0, 1.0, 1.0], 7.0)); // touching
        assert_eq!(r.validate(&g), Ok(()));
    }

    #[test]
    fn rejects_invalid() {
        let g = geom();
        let with = |f: &dyn Fn(&mut DielectricRegions)| {
            let mut r = DielectricRegions {
                boxes: vec![dbox([2.0, 0.0, 0.0, 3.0, 1.0, 1.0], 7.0)],
                conformal: vec![rule(vec![BoxId::new(0)], 0.03, 0.0)],
            };
            f(&mut r);
            r.validate(&g).unwrap_err()
        };
        assert!(with(&|r| r.boxes[0].eps_r = 0.5).contains("eps_r"));
        assert!(
            with(&|r| r.boxes.push(dbox([2.5, 0.5, 0.5, 4.0, 2.0, 2.0], 2.0))).contains("overlap")
        );
        assert!(with(&|r| r.conformal[0].eps_r = f64::NAN).contains("eps_r"));
        assert!(with(&|r| r.conformal[0].side = -1.0).contains(">= 0"));
        assert!(with(&|r| r.conformal[0].side = 0.0).contains("both"));
        assert!(with(&|r| r.conformal[0].boxes.push(BoxId::new(5))).contains("unknown"));
        assert!(with(&|r| r.conformal[0].boxes.push(BoxId::new(0))).contains("twice"));
    }

    #[test]
    fn overlap_sweep_matches_pairs() {
        // Boxes along a diagonal, one pair overlapping deep in the list.
        let mut boxes: Vec<DielectricBox> = (0..50)
            .map(|i| {
                let x = f64::from(i) * 2.0;
                dbox([x, 0.0, 0.0, x + 1.0, 1.0, 1.0], 2.0)
            })
            .collect();
        assert_eq!(first_overlap(&boxes), None);
        boxes.push(dbox([60.5, 0.5, 0.5, 61.5, 2.0, 2.0], 2.0)); // overlaps box 30
        assert_eq!(first_overlap(&boxes), Some((30, 50)));
    }
}
